// src/context/AuthContext.js
import React, { createContext, useContext, useEffect, useState } from 'react';
import {
  getAuth,
  signInWithEmailAndPassword,
  createUserWithEmailAndPassword,
  signInWithPopup,
  GoogleAuthProvider,
  signOut,
  updateProfile,
  deleteUser,
  reauthenticateWithCredential,
  EmailAuthProvider,
} from 'firebase/auth';
import {
  getFirestore,
  doc,
  setDoc,
  getDoc,
  updateDoc,
  deleteDoc,
} from 'firebase/firestore';
import {
  getStorage,
  ref,
  uploadBytes,
  getDownloadURL,
  deleteObject,
} from 'firebase/storage';
import { initializeApp } from 'firebase/app';

// ── Firebase config ── put your real values here (or import from firebaseConfig.js)
const firebaseConfig = {
  apiKey:            process.env.REACT_APP_FIREBASE_API_KEY,
  authDomain:        process.env.REACT_APP_FIREBASE_AUTH_DOMAIN,
  projectId:         process.env.REACT_APP_FIREBASE_PROJECT_ID,
  storageBucket:     process.env.REACT_APP_FIREBASE_STORAGE_BUCKET,
  messagingSenderId: process.env.REACT_APP_FIREBASE_MESSAGING_SENDER_ID,
  appId:             process.env.REACT_APP_FIREBASE_APP_ID,
};

const app  = initializeApp(firebaseConfig);
const auth = getAuth(app);
const db   = getFirestore(app);
const storage = getStorage(app);

const AuthContext = createContext(null);

export function AuthProvider({ children }) {
  const [user,    setUser]    = useState(null);
  const [profile, setProfile] = useState(null);
  const [loading, setLoading] = useState(true);

  // Listen to Firebase auth state
  useEffect(() => {
    const unsub = auth.onAuthStateChanged(async (firebaseUser) => {
      setUser(firebaseUser);
      if (firebaseUser) {
        // Store token for axios calls
        const token = await firebaseUser.getIdToken();
        localStorage.setItem('token', token);
        // Load Firestore profile
        const snap = await getDoc(doc(db, 'users', firebaseUser.uid));
        if (snap.exists()) setProfile(snap.data());
      } else {
        localStorage.removeItem('token');
        setProfile(null);
      }
      setLoading(false);
    });
    return unsub;
  }, []);

  // Get a fresh token (used by axios calls in pages)
  const getToken = async () => {
    if (!user) return null;
    return user.getIdToken(/* forceRefresh */ true);
  };

  // Sign up with email
  const signup = async (email, password, displayName) => {
    const cred = await createUserWithEmailAndPassword(auth, email, password);
    await updateProfile(cred.user, { displayName });
    await setDoc(doc(db, 'users', cred.user.uid), {
      displayName,
      email,
      organization:     '',
      country:          '',
      bio:              '',
      photoURL:         '',
      totalPredictions: 0,
      createdAt:        new Date().toISOString(),
    });
    return cred;
  };

  // Sign in with email
  const login = (email, password) =>
    signInWithEmailAndPassword(auth, email, password);

  // Google sign-in
  const loginWithGoogle = async () => {
    const provider = new GoogleAuthProvider();
    const cred = await signInWithPopup(auth, provider);
    // Create Firestore doc if first time
    const ref = doc(db, 'users', cred.user.uid);
    const snap = await getDoc(ref);
    if (!snap.exists()) {
      await setDoc(ref, {
        displayName:      cred.user.displayName || '',
        email:            cred.user.email,
        organization:     '',
        country:          '',
        bio:              '',
        photoURL:         cred.user.photoURL || '',
        totalPredictions: 0,
        createdAt:        new Date().toISOString(),
      });
    }
    return cred;
  };

  // Logout
  const logout = async () => {
    await signOut(auth);
    localStorage.removeItem('token');
  };

  // Update profile fields
  const updateUserProfile = async (fields) => {
    if (!user) return;
    await updateDoc(doc(db, 'users', user.uid), fields);
    if (fields.displayName) {
      await updateProfile(user, { displayName: fields.displayName });
    }
    setProfile(p => ({ ...p, ...fields }));
  };

  // Upload profile picture
  const uploadProfilePicture = async (file) => {
    if (!user) return;
    const storageRef = ref(storage, `avatars/${user.uid}`);
    await uploadBytes(storageRef, file);
    const url = await getDownloadURL(storageRef);
    await updateProfile(user, { photoURL: url });
    await updateDoc(doc(db, 'users', user.uid), { photoURL: url });
    setProfile(p => ({ ...p, photoURL: url }));
  };

  // Remove profile picture
  const removeProfilePicture = async () => {
    if (!user) return;
    try {
      await deleteObject(ref(storage, `avatars/${user.uid}`));
    } catch (_) { /* ignore if no file */ }
    await updateProfile(user, { photoURL: '' });
    await updateDoc(doc(db, 'users', user.uid), { photoURL: '' });
    setProfile(p => ({ ...p, photoURL: '' }));
  };

  // Delete account
  const deleteAccount = async (password) => {
    if (!user) return;
    // Re-authenticate first
    const credential = EmailAuthProvider.credential(user.email, password);
    await reauthenticateWithCredential(user, credential);
    // Delete Firestore data
    await deleteDoc(doc(db, 'users', user.uid));
    // Delete Firebase user
    await deleteUser(user);
    localStorage.removeItem('token');
  };

  const value = {
    user,
    profile,
    loading,
    getToken,
    signup,
    login,
    loginWithGoogle,
    logout,
    updateUserProfile,
    uploadProfilePicture,
    removeProfilePicture,
    deleteAccount,
  };

  // Don't render children until auth state is known
  if (loading) return null;

  return (
    <AuthContext.Provider value={value}>
      {children}
    </AuthContext.Provider>
  );
}

export const useAuth = () => useContext(AuthContext);
